import React, { forwardRef, useState } from 'react';
import { usePopper } from 'react-popper';
import styled from 'styled-components';

import Borders from '@dynatrace/strato-design-tokens/borders';
import BoxShadows from '@dynatrace/strato-design-tokens/box-shadows';
import Colors from '@dynatrace/strato-design-tokens/colors';
import Spacings from '@dynatrace/strato-design-tokens/spacings';

import { StyledLabel } from './Label.js';
import { ALIGN_OFFSET } from './SubContent.js';
import type { WithChildren } from '../../core/types/with-children.js';

export interface MenuItemTooltipWrapperProps extends WithChildren {
  triggerElement: HTMLElement | null;
}

export type MenuItemTooltipProps = WithChildren;

// FIXME: Move to pure object notation
/**
 * The styled item tooltip. Exported for visual reuse (example: chart tooltip).
 * @internal
 */
const MenuItemTooltip = styled.div`
  ${StyledLabel} {
    padding: ${Spacings.Size4} ${Spacings.Size0} ${Spacings.Size8};
  }
`;

const StyledMenuItemTooltipWrapper = styled.div({
  background: Colors.Background.Surface.Default,
  borderRadius: Borders.Radius.Surface.Subdued,
  boxShadow: BoxShadows.Surface.Floating.Rest,
  padding: Spacings.Size8,
  minWidth: '150px',
  maxWidth: '500px',
});

/** @internal */
export const MenuItemTooltipWrapper = ({
  triggerElement,
  children,
}: MenuItemTooltipWrapperProps) => {
  const [menuTooltipRefRef, setMenuTooltipRefRef] =
    useState<HTMLDivElement | null>(null);

  const { styles, attributes } = usePopper(triggerElement, menuTooltipRefRef, {
    placement: 'right-start',
    modifiers: [
      {
        name: 'offset',
        options: {
          offset: [ALIGN_OFFSET, 0],
        },
      },
      {
        name: 'flip',
        options: {
          fallbackPlacements: ['left-start'],
        },
      },
    ],
  });

  return (
    <StyledMenuItemTooltipWrapper
      ref={setMenuTooltipRefRef}
      style={styles.popper}
      {...attributes.popper}
    >
      {children}
    </StyledMenuItemTooltipWrapper>
  );
};
MenuItemTooltipWrapper.displayName = 'MenuItemTooltipWrapper';

/**
 * A tooltip which can be used as a child of an Item. Its content will appear
 * in an overlay when the Item is focused.
 */
export const ItemTooltip = forwardRef<HTMLDivElement, MenuItemTooltipProps>(
  ({ children }, forwardedRef) => {
    return children ? (
      <MenuItemTooltip ref={forwardedRef}>{children}</MenuItemTooltip>
    ) : null;
  },
);

(ItemTooltip as typeof ItemTooltip & { displayName: string }).displayName =
  'Menu.ItemTooltip';
